export interface GameDescriptor { apiVersion: 1; id: string; name: string; status: 'early-access' | 'test-fixture'; playable: boolean; capabilities: string[]; requirements: string[]; widgets: string[]; actions: string[]; safety: string[] }
export interface WorkProgress { completed: number; total: number; unit: string; basis: string }
export interface WorkspaceResource { id: string; kind: 'raw' | 'placement'; projectId: string; projectName: string; name: string; required: number; inventory: number | null; storage: number; storageObservedAt: string | null; reservedElsewhere: number; verifiedPlaced: number; remainingToPlace: number; availableForProject: number | null; missing: number | null; userAssigned: number; agentAssigned: number; userReported: number; agentAllocated: number; source: string; difficulty: string; reason: string; gathering: boolean }
export interface AssistanceRequest { id: string; revision: number; type: string; title: string; detail: string; status: 'pending' | 'accepted' | 'deferred' | 'resolved'; priority: 'normal' | 'urgent'; projectId?: string; item?: string; count?: number; taskId?: string; owner?: 'player' | 'companion'; updatedAt: string; resolution?: string; actions: ('player' | 'companion' | 'replan' | 'defer')[] }
export interface WorkspaceTask { id: string; title: string; status: string; owner: string; revision?:number; error?: string; step?: number; steps?: number; actions: {tool: string; args: Record<string, unknown>}[] }
export interface WorkspaceSnapshot { schemaVersion: 1; game: GameDescriptor; session: {id: string; gameId: string; status: string; connected: boolean; observedAt: string | null; stale: boolean}; companion: {name: string; status: string}; activity: {state: string; label: string; detail: string; tool: string | null; progress: WorkProgress | null; next: string[]}; mission: {id: string; title: string; status: string; progress: WorkProgress | null; sections: {name: string; verified: number; total: number}[]; verifiedAt: string | null} | null; resources: WorkspaceResource[]; assistance: AssistanceRequest[]; tasks: WorkspaceTask[]; environment: {position: {x:number;y:number;z:number} | null; dimension: string | null; health: number | null; food: number | null; observedAt: string | null}; storage: {id:string;name:string;observedAt:string|null;stale:boolean;inventory:{name:string;count:number}[];realmId:number;dimension:string}[] }
export interface GameAdapter { descriptor: GameDescriptor; project(state: unknown, context?: unknown): WorkspaceSnapshot }
export function createGameRegistry(adapters: GameAdapter[], options?: { allowFixtures?: boolean }): { list(): GameDescriptor[]; get(id: string): GameAdapter; project(id: string, state: unknown, context?: unknown): WorkspaceSnapshot };
